import React from "react";
import { Link, useNavigate } from "react-router-dom";
import "../Styles/Header.css"; // تأكد أن اسم الملف صحيح

const Header = () => {
  const navigate = useNavigate();

  // 🔸 نقرأ بيانات المستخدم من localStorage
  const role = localStorage.getItem("role");
  const user = JSON.parse(localStorage.getItem("loggedUser"));

  // 🔸 دالة تسجيل الخروج
  const handleLogout = () => {
    localStorage.removeItem("role");
    localStorage.removeItem("loggedUser");
    navigate("/login");
  };

  return (
    <header className="header">
      {/* ✅ الشعار */}
      <div className="brand">
        <div className="logo-circle">U</div>
        <div className="brand-text">
          <span className="brand-main">UTAS</span>
          <span className="brand-accent">Link</span>
        </div>
      </div>

      {/* ✅ روابط التنقل */}
      <nav className="nav-links">
        {/* الحالة 1: المستخدم ما سجل دخول */}
        {!role && (
          <Link to="/home" className="btn-get-started">
            Get Started
          </Link>
        )}

        {/* الحالة 2: الطالب */}
        {role === "student" && (
          <>
            <Link to="/user-profile">My Profile</Link>
            <Link to="/find-job">Find Jobs</Link>
            <Link to="/my-applications">My Applications</Link>
            <button className="logout-btn" onClick={handleLogout}>
              Logout
            </button>
          </>
        )}

        {/* الحالة 3: الشركة */}
        {role === "company" && (
          <>
            <Link to="/company-profile">Company Profile</Link>
            <Link to="/post-job">Post a Job</Link>
            <Link to="/company-jobs">My Jobs</Link>
            <button className="logout-btn" onClick={handleLogout}>
              Logout
            </button>
          </>
        )}
      </nav>
    </header>
  );
};

export default Header;
